89	func (m *ResidentGitMemo) get(key string) ([]byte, bool) {
90		m.mu.Lock()
91		defer m.mu.Unlock()
92		el, ok := m.entries[key]
93		if !ok {
94			m.misses.Add(1)
95			return nil, false
96		}
97		m.order.MoveToFront(el)
98		m.hits.Add(1)
99		return append([]byte(nil), el.Value.(*residentGitEntry).stdout...), true
100	}
