102	func (m *ResidentGitMemo) put(key string, stdout []byte) {
103		size := int64(len(key) + len(stdout))
104		m.mu.Lock()
105		defer m.mu.Unlock()
106		if size > m.max {
107			return
108		}
109		if el, ok := m.entries[key]; ok {
110			m.bytes -= int64(len(el.Value.(*residentGitEntry).key) + len(el.Value.(*residentGitEntry).stdout))
111			m.order.Remove(el)
112			delete(m.entries, key)
113		}
114		for m.bytes+size > m.max {
115			last := m.order.Back()
116			if last == nil {
117				break
118			}
119			e := last.Value.(*residentGitEntry)
120			m.bytes -= int64(len(e.key) + len(e.stdout))
121			m.order.Remove(last)
122			delete(m.entries, e.key)
123		}
124		m.entries[key] = m.order.PushFront(&residentGitEntry{key: key, stdout: append([]byte(nil), stdout...)})
125		m.bytes += size
126	}
